import { InitiateAuthCommand } from '@aws-sdk/client-cognito-identity-provider'
import { cognitoClient, resolveCognitoConfig, type CognitoConfig } from '@nexo/shared/aws'
import { env } from '../env'

export const cognito = cognitoClient(env)

let config: Promise<CognitoConfig> | undefined
/** Pool and client ids are generated by cognito-local, so they are discovered by name (cached). */
export const cognitoConfig = () => (config ??= resolveCognitoConfig(cognito, env))

export type Tokens = { accessToken: string; idToken: string }

/** USER_PASSWORD_AUTH login, the same flow the web app uses. */
export async function login(email: string, password = env.SEED_PASSWORD): Promise<Tokens> {
  const { clientId } = await cognitoConfig()
  const res = await cognito.send(
    new InitiateAuthCommand({
      AuthFlow: 'USER_PASSWORD_AUTH',
      ClientId: clientId,
      AuthParameters: { USERNAME: email, PASSWORD: password },
    }),
  )
  const accessToken = res.AuthenticationResult?.AccessToken
  const idToken = res.AuthenticationResult?.IdToken
  if (!accessToken || !idToken) throw new Error(`login for ${email} returned no tokens`)
  return { accessToken, idToken }
}
